-- Grant the least-privilege app role access to every snake_case view.
DO $$
DECLARE v record;
BEGIN
  FOR v IN SELECT viewname FROM pg_views WHERE schemaname = 'public' AND viewname = lower(viewname) LOOP
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON %I TO nid_app', v.viewname);
  END LOOP;
END $$;

